import math
def POLY(id,pts,fill="#BBDEFB",stroke="#1E88E5",w=5): part("raw",id,{"kind":"poly","points":pts,"fill":fill,"stroke":stroke,"width":w})
S=["1 Compass and circle","2 Waves and arcs","3 Squares and rectangles","4 Construct a square","5 The XY puzzle","6 Diagonals","7 Rectangle from a diagonal","8 Equidistant points","9 Dot grid squares","10 The XY table","11 Diagonal angles","12 Circle art","13 Construct a house","14 Eyes, waves, rhombus","15 A Person and waves","16 Breaking rectangles","Mixed practice"]
def C(id,cx,cy,r,fill="#F1F8FF",stroke="#1E88E5",w=4): part("raw",id,{"kind":"circle","cx":cx,"cy":cy,"r":r,"fill":fill,"stroke":stroke,"width":w})
def DT(id,x,y,r=7,fill="#E53935"): part("raw",id,{"kind":"circle","cx":round(x,1),"cy":round(y,1),"r":r,"fill":fill,"stroke":"#16253F","width":2})
def ARC(id,cx,cy,r,a1,a2,c="#E65100",w=5):
    n=18; pts=[]
    for k in range(n+1):
        a=math.radians(a1+(a2-a1)*k/n); pts.append((round(cx+r*math.cos(a),1),round(cy-r*math.sin(a),1)))
    d="M "+" L ".join(f"{x} {y}" for x,y in pts)
    part("raw",id,{"kind":"path","d":d,"stroke":c,"width":w})
def RA(id,x,y,dx,dy,s=16): # right-angle mark at corner (x,y) with directions dx,dy
    POLY(id,[[x,y],[x+dx*s,y],[x+dx*s,y+dy*s],[x,y+dy*s]],fill="#FFF3E0",stroke="#E65100",w=2)
def Pt(id,x,y,name,dx=-18,dy=-12,c=None,s=26):
    DT(id,x,y); L(name,id+"n",y=y+dy,s=s,c=c or "#16253F",x=x+dx)
def tx(*a,**k): L(*a,**k)
